async function load(){const t=ticket(),seq=++listSeq,key=queryKey();items.value=[];total.value=0;error.value='';if(!current(t)||!props.governance&&(!bedPositive(department.value)||!bedPositive(ward.value)))return;loading.value=true;try{const params={...(department.value?{department_id:department.value}:{}),...(ward.value?{ward_id:ward.value}:{}),...(status.value?{status:status.value}:{}),page:page.value,page_size:20},response=await(props.governance?getAdminBedSources({...params,kind:kind.value}):getBedSources(kind.value,params)),data=response.data;if(!current(t)||seq!==listSeq||key!==queryKey())return;if(!Array.isArray(data?.items)||!Number.isSafeInteger(data.total)||data.total<0||data.page!==page.value||data.page_size!==20||data.items.length>20||data.items.length>data.total||new Set(data.items.map(row=>row.source_record_id)).size!==data.items.length||data.items.some(row=>!bedMetadataValid(row,kind.value,department.value||null,ward.value||null)||status.value&&row.status!==status.value))throw new Error('原来源目录与明确病区、科室或治理版本不一致');items.value=data.items;total.value=data.total;}catch(failure){if(current(t)&&seq===listSeq&&key===queryKey()){detailOpen.value=false;clearDetail();error.value=failure?.message||'原来源当前访问无法重新核对，已清除旧正文';}}finally{if(current(t)&&seq===listSeq)loading.value=false;}}
